import{_ as o,a0 as p,w as r,s as d,I as i,x as a,a1 as l,A as t,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"網絡分析利器：在 Ubuntu 16.04 上安裝 Bro | LCTT x X-CMD","titleTemplate":false,"description":"網絡分析利器：在 Ubuntu 16.04 上安裝 Bro | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"網絡分析利器：在 Ubuntu 16.04 上安裝 Bro | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"網絡分析利器：在 Ubuntu 16.04 上安裝 Bro | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04","title":"網絡分析利器：在 Ubuntu 16.04 上安裝 Bro","tag":"201707","desc":""},"relativePath":"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04.md","filePath":"[post].md"}'),h={name:"201707/20170628 Network Analysis How To Install Bro On Ubuntu 16.04.md"};function g(b,s,c,u,k,f){const e=p("Link");return r(),d("div",null,[s[24]||(s[24]=i("h1",{id:"網絡分析利器-在-ubuntu-16-04-上安裝-bro",tabindex:"-1"},[a("網絡分析利器：在 Ubuntu 16.04 上安裝 Bro "),i("a",{class:"header-anchor",href:"#網絡分析利器-在-ubuntu-16-04-上安裝-bro","aria-label":"Permalink to “網絡分析利器：在 Ubuntu 16.04 上安裝 Bro”"},"​")],-1)),i("p",null,[l(e,{href:"https://www.unixmen.com/wp-content/uploads/2017/07/brologo.jpg"},{default:t(()=>[...s[0]||(s[0]=[i("img",{src:"https://www.unixmen.com/wp-content/uploads/2017/07/brologo-696x696.jpg",alt:"Bro Network Analysis Logo",title:"brologo"},null,-1)])]),_:1})]),s[25]||(s[25]=n('<h3 id="簡介-bro-網絡分析框架" tabindex="-1">簡介：Bro 網絡分析框架 <a class="header-anchor" href="#簡介-bro-網絡分析框架" aria-label="Permalink to “簡介：Bro 網絡分析框架”">​</a></h3><p>Bro 是一個開源的網絡分析框架，側重於網絡安全監控。這是一項長達 15 年的研究成果，被各大學、研究實驗室、超級計算機中心和許多開放科學界廣泛使用。它主要由伯克利國際計算機科學研究所和伊利諾伊大學厄巴納-香檳分校的國家超級計算機應用中心開發。</p><p>Bro 的功能包括：</p><ul><li>Bro 的腳本語言支持針對站點定製監控策略</li><li>針對高性能網絡</li><li>分析器支持許多協議，可以在應用層面實現高級語義分析</li><li>它保留了其所監控的網絡的豐富的應用層統計信息</li><li>Bro 能夠與其他應用程序接口實時地交換信息</li><li>它的日誌全面地記錄了一切信息，並提供網絡活動的高級存檔</li></ul><p>本教程將介紹如何從源代碼構建，並在 Ubuntu 16.04 服務器上安裝 Bro。</p><h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3><p>Bro 有許多依賴文件:</p>',7)),i("ul",null,[i("li",null,[s[2]||(s[2]=a("Libpcap (",-1)),l(e,{href:"http://www.tcpdump.org/"},{default:t(()=>[...s[1]||(s[1]=[a("http://www.tcpdump.org",-1)])]),_:1}),s[3]||(s[3]=a(")",-1))]),i("li",null,[s[5]||(s[5]=a("OpenSSL 庫 (",-1)),l(e,{href:"http://www.openssl.org/"},{default:t(()=>[...s[4]||(s[4]=[a("http://www.openssl.org",-1)])]),_:1}),s[6]||(s[6]=a(")",-1))]),s[7]||(s[7]=i("li",null,"BIND8 庫",-1)),s[8]||(s[8]=i("li",null,"Libz",-1)),s[9]||(s[9]=i("li",null,"Bash (BroControl 所需要)",-1)),s[10]||(s[10]=i("li",null,"Python 2.6+ (BroControl 所需要)",-1))]),s[26]||(s[26]=n(`<p>從源代碼構建還需要：</p><ul><li>CMake 2.8+</li><li>Make</li><li>GCC 4.8+ or Clang 3.3+</li><li>SWIG</li><li>GNU Bison</li><li>Flex</li><li>Libpcap headers</li><li>OpenSSL headers</li><li>zlib headers</li></ul><h3 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to “起步”">​</a></h3><p>首先，通過執行以下命令來安裝所有必需的依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install cmake make gcc g++ flex bison libpcap-dev libssl-dev python-dev swig zlib1g-dev</span></span></code></pre></div><h4 id="安裝定位-ip-地理位置的-geoip-資料庫" tabindex="-1">安裝定位 IP 地理位置的 GeoIP 資料庫 <a class="header-anchor" href="#安裝定位-ip-地理位置的-geoip-資料庫" aria-label="Permalink to “安裝定位 IP 地理位置的 GeoIP 資料庫”">​</a></h4><p>Bro 使用 GeoIP 的定位地理位置。安裝 IPv4 和 IPv6 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://geolite.maxmind.com/download/geoip/database/GeoLiteCity.dat.gz</span></span>
<span class="line"><span>$wget http://geolite.maxmind.com/download/geoip/database/GeoLiteCityv6-beta/GeoLiteCityv6.dat.gz</span></span></code></pre></div><p>解壓這兩個壓縮包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -d GeoLiteCity.dat.gz</span></span>
<span class="line"><span>$ gzip -d GeoLiteCityv6.dat.gz</span></span></code></pre></div><p>將解壓後的文件移動到 <code>/usr/share/GeoIP</code> 目錄下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mvGeoLiteCity.dat /usr/share/GeoIP/GeoIPCity.dat</span></span>
<span class="line"><span># mv GeoLiteCityv6.dat /usr/share/GeoIP/GeoIPCityv6.dat</span></span></code></pre></div><p>現在，可以從源代碼構建 Bro 了。</p><h3 id="構建-bro" tabindex="-1">構建 Bro <a class="header-anchor" href="#構建-bro" aria-label="Permalink to “構建 Bro”">​</a></h3><p>最新的 Bro 開發版本可以通過 <code>git</code> 倉庫獲得。執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone --recursive git://git.bro.org/bro</span></span></code></pre></div><p>轉到克隆下來的目錄，然後使用以下命令就可以簡單地構建 Bro：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd bro</span></span>
<span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span></code></pre></div><p><code>make</code> 命令需要一些時間來構建一切。確切的時間取決於服務器的性能。</p><p>可以使用一些參數來執行 <code>configure</code> 腳本，以指定要構建的依賴關係，特別是 <code>--with-*</code> 選項。</p><h3 id="安裝-bro" tabindex="-1">安裝 Bro <a class="header-anchor" href="#安裝-bro" aria-label="Permalink to “安裝 Bro”">​</a></h3><p>在克隆的 <code>bro</code> 目錄中執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># make install</span></span></code></pre></div><p>默認安裝路徑為 <code>/usr/local/bro</code>。</p><h3 id="配置-bro" tabindex="-1">配置 Bro <a class="header-anchor" href="#配置-bro" aria-label="Permalink to “配置 Bro”">​</a></h3><p>Bro 的配置文件位於 <code>/usr/local/bro/etc</code> 目錄下。 這裏有三個文件:</p><ul><li><code>node.cfg</code>，用於配置要監視的單個節點（或多個節點）。</li><li><code>broctl.cfg</code>，BroControl 的配置文件。</li><li><code>networks.cgf</code>，包含一個使用 CIDR 標記法表示的網絡列表。</li></ul><h4 id="配置郵件設置" tabindex="-1">配置郵件設置 <a class="header-anchor" href="#配置郵件設置" aria-label="Permalink to “配置郵件設置”">​</a></h4><p>打開 <code>broctl.cfg</code> 配置文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/broctl.cfg</span></span></code></pre></div><p>查看 <code>Mail Options</code> 選項，並編輯 <code>MailTo</code> 行如下:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Recipient address for emails sent out by Bro and BroControl</span></span>
<span class="line"><span>MailTo = admin@example.com</span></span></code></pre></div><p>保存並關閉。還有許多其他選項，但在大多數情況下，默認值就足夠好了。</p><h4 id="選擇要監視的節點" tabindex="-1">選擇要監視的節點 <a class="header-anchor" href="#選擇要監視的節點" aria-label="Permalink to “選擇要監視的節點”">​</a></h4><p>開箱即用，Bro 被配置為以獨立模式運行。在本教程中，我們就是做一個獨立的安裝，所以沒有必要改變。但是，也請查看 <code>node.cfg</code> 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/node.cfg</span></span></code></pre></div><p>在 <code>[bro]</code> 部分，你應該看到這樣的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[bro]</span></span>
<span class="line"><span>type=standalone</span></span>
<span class="line"><span>host=localhost</span></span>
<span class="line"><span>interface=eth0</span></span></code></pre></div><p>請確保 <code>inferface</code> 與 Ubuntu 16.04 服務器的公網接口相匹配。</p><p>保存並退出。</p><h4 id="配置監視節點的網絡" tabindex="-1">配置監視節點的網絡 <a class="header-anchor" href="#配置監視節點的網絡" aria-label="Permalink to “配置監視節點的網絡”">​</a></h4><p>最後一個要編輯的文件是 <code>network.cfg</code>。使用文本編輯器打開它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /usr/local/bro/etc/networks.cfg</span></span></code></pre></div><p>默認情況下，你應該看到以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List of local networks in CIDR notation, optionally followed by a</span></span>
<span class="line"><span># descriptive tag.</span></span>
<span class="line"><span># For example, &quot;10.0.0.0/8&quot; or &quot;fe80::/64&quot; are valid prefixes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10.0.0.0/8          Private IP space</span></span>
<span class="line"><span>172.16.0.0/12       Private IP space</span></span>
<span class="line"><span>192.168.0.0/16      Private IP space</span></span></code></pre></div><p>刪除這三個條目（這只是如何使用此文件的示例），並輸入服務器的公用和專用 IP 空間，格式如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>X.X.X.X/X        Public IP space</span></span>
<span class="line"><span>X.X.X.X/X        Private IP space</span></span></code></pre></div><p>保存並退出。</p><h3 id="使用-brocontrol-管理-bro-的安裝" tabindex="-1">使用 BroControl 管理 Bro 的安裝 <a class="header-anchor" href="#使用-brocontrol-管理-bro-的安裝" aria-label="Permalink to “使用 BroControl 管理 Bro 的安裝”">​</a></h3><p>管理 Bro 需要使用 BroControl，它支持交互式 shell 和命令列工具兩種形式。啓動該 shell：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/local/bro/bin/broctl</span></span></code></pre></div><p>要想使用命令列工具，只需將參數傳遞給上一個命令，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/local/bro/bin/broctl status</span></span></code></pre></div><p>這將通過顯示以下的輸出來檢查 Bro 的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name         Type       Host          Status    Pid    Started</span></span>
<span class="line"><span>bro          standalone localhost     running   6807   20 Jul 12:30:50</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這是一篇 Bro 的安裝教程。我們使用基於源代碼的安裝，因為它是獲得可用的最新版本的最有效的方法，但是該網絡分析框架也可以下載預構建的二進制格式文件。</p><p>下次見！</p><hr>`,59)),i("p",null,[s[12]||(s[12]=a("via: ",-1)),l(e,{href:"https://www.unixmen.com/how-to-install-bro-ubuntu-1604/"},{default:t(()=>[...s[11]||(s[11]=[a("https://www.unixmen.com/how-to-install-bro-ubuntu-1604/",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("作者：",-1)),l(e,{href:"https://www.unixmen.com/author/tutan/"},{default:t(()=>[...s[13]||(s[13]=[a("Giuseppe Molica",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),l(e,{href:"https://github.com/firmianay"},{default:t(()=>[...s[14]||(s[14]=[a("firmianay",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const v=o(h,[["render",g]]);export{C as __pageData,v as default};
